questionvariables.text:
/* Design: decide from three graphs whether the trapezoidal estimate is too large or too small. Shapes 1-3 bend upwards (U), 4-6 bend downwards (D), 7-8 are straight (L); the largest chord gap on each curved shape is at least 0.2 units. SD: [permutation index, U variant, D variant, L variant]. The U graph sits at A, B, C on 3, 4, 3 seeds. Source: adapted from SMP AS/A2 Core 2, Chapter 9, C1. */
PERM: [["U","D","L"],["U","L","D"],["D","U","L"],["D","L","U"],["L","U","D"],["L","D","U"]];
SD: [[1,1,2,1],[2,2,3,2],[3,3,1,1],[4,1,2,2],[5,2,3,1],[6,3,1,2],[1,2,1,2],[3,1,3,1],[5,3,2,2],[6,1,3,1]];
ix: 1+rand(10);
pm: PERM[SD[ix][1]]; uv: SD[ix][2]; dv: SD[ix][3]; lv: SD[ix][4];
sh: makelist(if pm[p]="U" then uv elseif pm[p]="D" then 3+dv else 6+lv, p, 1, 3);
DS: ["a curve rising more and more steeply from near the bottom, with two trapezia under it","a curve that falls and then levels out and rises a little, with two trapezia under it","a curve that is almost flat and then rises very steeply, with two trapezia under it",
     "a curve that rises to a broad hump and falls a little, with two trapezia under it","a curve that falls more and more steeply from the top, with two trapezia under it","a curve that rises steeply at first and then more and more gently, with two trapezia under it",
     "a straight line rising from left to right, with two trapezia under it","a straight line falling from left to right, with two trapezia under it"];
desc1: DS[sh[1]]; desc2: DS[sh[2]]; desc3: DS[sh[3]];
pU: sublist_indices(pm, lambda([t], t="U"))[1];
pD: sublist_indices(pm, lambda([t], t="D"))[1];
pL: sublist_indices(pm, lambda([t], t="L"))[1];
mk(t) := [["ct",false,"cannot tell from the graph"],["ov",is(t="U"),"an overestimate"],["un",is(t="D"),"an underestimate"],["ex",is(t="L"),"exact"]];
o1: mk(pm[1]); o2: mk(pm[2]); o3: mk(pm[3]);
kv: makelist(if pm[p]="U" then "ov" elseif pm[p]="D" then "un" else "ex", p, 1, 3);
opts: [["r1",false,"The strips are not all the same width."],["r2",true,"The straight top of each trapezium lies above the curve, so each trapezium includes some area that is not under the curve."],["r3",false,"The straight top of each trapezium lies below the curve, so some area under the curve is left out."],["r4",false,"The trapezoidal rule always gives an overestimate."]];
/* test inputs */
swv: makelist(if pm[p]="U" then "un" elseif pm[p]="D" then "ov" else "ex", p, 1, 3);
lwv: makelist(if pm[p]="L" then "ov" else kv[p], p, 1, 3);
uxv: makelist(if pm[p]="U" then "ex" else kv[p], p, 1, 3);

feedbackvariables.text:
aa: [ans1,ans2,ans3];
swp: is(aa[pU]="un" and aa[pD]="ov");
lw: is(aa[pL]#"ex");
nc: length(sublist([1,2,3], lambda([p], aa[p]=kv[p])));
gwl: makelist(if aa[p]=kv[p] then 0 elseif aa[p]="ct" then 1 elseif aa[p]="ov" then 2 elseif aa[p]="un" then 3 else 4, p, 1, 3);
gw1: gwl[1]; gw2: gwl[2]; gw3: gwl[3];
